import{_ as e}from"./chunks/tier-kits.CX-RPaZj.js";import{_ as d,o as a,c as r,a2 as n}from"./chunks/framework.CN568Poi.js";const b=JSON.parse('{"title":"Collection and processing","description":"","frontmatter":{},"headers":[],"relativePath":"collection.md","filePath":"collection.md","lastUpdated":1795431209000}'),o={name:"collection.md"};function s(i,t,c,l,h,p){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="collection-and-processing" tabindex="-1">Collection and processing <a class="header-anchor" href="#collection-and-processing" aria-label="Permalink to &quot;Collection and processing&quot;">​</a></h1><p align="center"><img src="'+e+'" alt="Instrumentation by tier" width="100%"><br><sub>The three kits: L1 headbands; L2 adds EMG armbands; L3 adds EEG, wrist cameras, eye tracker, gloves and trackers. Figure from the technical report.</sub></p><h2 id="hardware-configuration" tabindex="-1">Hardware configuration <a class="header-anchor" href="#hardware-configuration" aria-label="Permalink to &quot;Hardware configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Stream</th><th>Device (example)</th><th>Native resolution / channels</th><th>Rate</th><th>Unit</th></tr></thead><tbody><tr><td>L1</td><td>head RGB</td><td>14 third-party headbands, 13 vendors, 2–6 lenses</td><td>512×512–3840×1200</td><td>20–60 fps</td><td>RGB</td></tr><tr><td>L2</td><td>head RGB</td><td>four-camera headband, synchronized front pair</td><td>1920×1200</td><td>30 fps</td><td>RGB</td></tr><tr><td>L2/L3</td><td>wrist RGB</td><td>JIERUIWEITONG FH868</td><td>640×480 (up to 1920×1080 in some L2 releases)</td><td>30 fps</td><td>RGB</td></tr><tr><td>L3</td><td>eye scene camera</td><td>Pupil Labs Neon</td><td>1600×1200</td><td>30 fps</td><td>RGB</td></tr><tr><td>L3</td><td>third-person</td><td>Intel RealSense D455f</td><td>640×480</td><td>30 fps</td><td>RGB-D</td></tr><tr><td>L3</td><td>gaze</td><td>Pupil Labs Neon</td><td>x, y pixel</td><td>200 Hz</td><td>px</td></tr><tr><td>L3</td><td>head / wrist pose</td><td>HTC VIVE Tracker 3.0 ×3</td><td>6-DoF in one frame</td><td>≈800 Hz device</td><td>mm / deg</td></tr><tr><td>L3</td><td>fingers</td><td>MANUS Metaglove Pro</td><td>20 joints per hand</td><td>≈800 Hz device</td><td>deg</td></tr><tr><td>L2/L3</td><td>surface EMG</td><td>WLEMGUV2A ×2</td><td>8 ch per arm</td><td>2 kHz</td><td>mV</td></tr><tr><td>L3</td><td>EEG, controlled</td><td>Neuroscan SynAmps2</td><td>128 ch</td><td>1 kHz</td><td>µV</td></tr><tr><td>L3</td><td>EEG, open</td><td>BrainCo BCIGo</td><td>32/8 ch</td><td>250 Hz</td><td>µV</td></tr></tbody></table><p>Released streams may be downscaled; read <code>meta/info.json</code>. No instrument is daisy-chained: one host receives every stream and stamps arrival offsets, so each device keeps its clock and rate. A parallel-port box stamps phase/run transitions into the EEG amplifier.</p><h2 id="open-vs-controlled" tabindex="-1">Open vs. controlled <a class="header-anchor" href="#open-vs-controlled" aria-label="Permalink to &quot;Open vs. controlled&quot;">​</a></h2><p>L1 and L2 are collected in the <strong>open setting</strong>: wearable instruments, a headband computer, free movement. L2 and L3 use task sheets to stage objects and step order. L3 also has a <strong>controlled setting</strong> at a fixed desk, where dense EEG, eye tracking and motion capture require a still posture.</p><p>Controlled sessions run in two phases. <strong>Imagery:</strong> the screen turns blue, the operator sits still and rehearses the task while EEG and gaze are recorded. <strong>Execution:</strong> the screen turns green and the task is performed with every modality live. Phase markers (<code>run start</code>, <code>imagine</code>, <code>execute</code>, <code>run end</code>) let the phases be cut on a common time base.</p><h2 id="from-raw-signals-to-released-tables" tabindex="-1">From raw signals to released tables <a class="header-anchor" href="#from-raw-signals-to-released-tables" aria-label="Permalink to &quot;From raw signals to released tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What is done</th><th>What ships</th></tr></thead><tbody><tr><td>Synchronization and calibration</td><td>Samples stamped relative to episode start; arrival offsets recorded; cameras, trackers and eye tracker calibrated per session.</td><td>Timestamps, intrinsics, distortion, rectification and tracker transforms.</td></tr><tr><td>Geometry and motion</td><td>Depth from FoundationStereo on the synchronized pair; point clouds per frame; hands reconstructed over video windows and anchored in depth.</td><td>Depth, point clouds, head/wrist/chest pose and finger kinematics.</td></tr><tr><td>Gaze</td><td>Measured at 200 Hz by the eye tracker in controlled L3; predicted at 30 Hz elsewhere.</td><td><code>eye_gaze</code> and <code>eye_gaze_predict</code>.</td></tr><tr><td>EMG</td><td>Zero-phase 20–450 Hz band-pass and 50 Hz comb notch; raw and denoised traces kept.</td><td><code>*_emg_raw</code> / <code>*_emg_denoise</code>.</td></tr><tr><td>EEG</td><td>De-mean, 0.5–100 Hz band-pass, 50 Hz notch, bad-channel detection, ICA, interpolation and average reference.</td><td>Raw and cleaned EEG tables.</td></tr><tr><td>Annotation and QC</td><td>Argus over Qwen proposes step labels; a human reviews. Every session is checked after writing.</td><td>Structured annotation JSON, <code>qc_reports.jsonl</code>; failing sessions are recaptured.</td></tr></tbody></table><h2 id="privacy-and-license" tabindex="-1">Privacy and license <a class="header-anchor" href="#privacy-and-license" aria-label="Permalink to &quot;Privacy and license&quot;">​</a></h2><p>All participants gave written informed consent and could withdraw. Released episodes are de-identified; faces are blurred in every view. Data is CC BY-NC 4.0; code is Apache-2.0.</p>',12)])])}const f=d(o,[["render",s]]);export{b as __pageData,f as default};
